def is_kawaii(seq):
    # Condition: for each k >= 2, if k is in seq, then k-1 is in seq 
    # and first(k-1) < last(k)
    # Here, seq is a sequence of ranks (0, 1, 2, ...)
    # So if rank i is in seq, then i-1 is in seq and first(i-1) < last(i)
    for k in range(1, len(set(seq))):
        if k in seq:
            if (k-1) not in seq:
                return False
            first_prev = seq.index(k-1)
            last_curr = -1
            for i in range(len(seq)-1, -1, -1):
                if seq[i] == k:
                    last_curr = i
                    break
            if first_prev >= last_curr:
                return False
    return True

